import{_ as l,C as e,o as n,c as h,E as a,a2 as d}from"./chunks/framework.VWKgVqrc.js";const f=JSON.parse('{"title":"延迟下降以后，按期完成的任务为何仍可能不增加","description":"","frontmatter":{"title":"延迟下降以后，按期完成的任务为何仍可能不增加","date":"2026-11-04","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"完整任务的延迟改善何时不增加按期交付，成功样本筛选与计时窗口怎样影响读数？","summary":"固定截止期下，四个任务从 12 秒变为 11 秒仍全部超时；另一个对照仅改变成功标志，就使成功任务中位延迟下降。两种机制不能混写成实测加速。","sources":"固定版本的任务指标模块、同日内部实验及多智能体服务基准第二版论文","pageClass":"runtime-v6-article","item_id":"SIG-20261104-006","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-04-sig-20261104-006-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-11-04-sig-20261104-006.md","filePath":"zh/engineering/2026-11-04-sig-20261104-006.md","lastUpdated":null}'),s={name:"zh/engineering/2026-11-04-sig-20261104-006.md"};function g(o,t,c,p,x,u){const r=e("ArticleCover"),i=e("ArticleTableScroll");return n(),h("div",null,[a(r,{image:"/assets/covers/daily-2026-11-04-sig-20261104-006-cover.png",kicker:"研究成果",title:"延迟下降以后，按期完成的任务为何仍可能不增加",summary:"固定截止期下，四个任务从 12 秒变为 11 秒仍全部超时；另一个对照仅改变成功标志，就使成功任务中位延迟下降。两种机制不能混写成实测加速。",version:"2026-11-04",languageHref:"/en/engineering/2026-11-04-sig-20261104-006",languageLabel:"English"}),a(i,{language:"zh"}),t[0]||(t[0]=d('<h1 id="延迟下降以后-按期完成的任务为何仍可能不增加" tabindex="-1">延迟下降以后，按期完成的任务为何仍可能不增加 <a class="header-anchor" href="#延迟下降以后-按期完成的任务为何仍可能不增加" aria-label="Permalink to &quot;延迟下降以后，按期完成的任务为何仍可能不增加&quot;">​</a></h1><p>四个任务都从 12 秒变成 11 秒，按期完成数却仍然是零。若承诺的截止期是 10 秒，这个结果完全可能发生。另一个更容易误读的变化是：原始延迟没有动，仅把两个慢任务改为失败，成功任务的中位延迟便从 9 秒降到 5.5 秒。</p><p>对评估多智能体服务的工程师，这两种“变好”需要不同解释。前者没有跨过交付阈值，后者改变了统计人群。本次内部模块实验把它们分开：读者可以据此检查截止期、任务计数、分位数样本及计时窗口，不能据此选择一个已被证明更快的服务优化方案。</p><h2 id="四个任务-怎样变快却没有更多按期交付" tabindex="-1">四个任务，怎样变快却没有更多按期交付 <a class="header-anchor" href="#四个任务-怎样变快却没有更多按期交付" aria-label="Permalink to &quot;四个任务，怎样变快却没有更多按期交付&quot;">​</a></h2><p>同日研究执行 MAServeBench（多智能体服务基准）的<a href="https://raw.githubusercontent.com/ShengxuanQiu/MAServeBench/22483ab5df5eff562061953d564aac47a9423c2f/mas_workflow/app/semantic/metrics.py" target="_blank" rel="noreferrer">固定任务指标模块</a>，使用四个合成任务、20 秒观测时长和 10 秒截止期。每个任务均标为成功；成对对照只改原始墙钟延迟。这里的秒数是输入数组中的设定值，不是服务器上计时测得的完成时间。</p><table tabindex="0"><thead><tr><th>内部合成对照</th><th style="text-align:right;">每项延迟</th><th style="text-align:right;">尝试数</th><th style="text-align:right;">成功数</th><th style="text-align:right;">按期数</th><th style="text-align:right;">按期任务吞吐</th></tr></thead><tbody><tr><td>基准输入</td><td style="text-align:right;">12 秒</td><td style="text-align:right;">4</td><td style="text-align:right;">4</td><td style="text-align:right;">0</td><td style="text-align:right;">0 任务/秒</td></tr><tr><td>更快但仍超时</td><td style="text-align:right;">11 秒</td><td style="text-align:right;">4</td><td style="text-align:right;">4</td><td style="text-align:right;">0</td><td style="text-align:right;">0 任务/秒</td></tr><tr><td>恰好跨入边界</td><td style="text-align:right;">10 秒</td><td style="text-align:right;">4</td><td style="text-align:right;">4</td><td style="text-align:right;">4</td><td style="text-align:right;">0.2 任务/秒</td></tr></tbody></table><p>来源：同日内部实验的基准、更快但超时及截止边界三个模块对照；全部为合成输入。</p><p>公开代码将成功且延迟不大于截止期的任务计为按期完成，再用调用方提供的观测时长相除。因此前两行虽然延迟不同，阈值计数仍相同；到 10 秒时，包含边界的判断才使四项全部按期，得到 4÷20＝0.2 任务/秒。</p><p>这不是说 12 秒降到 11 秒没有价值，而是说它不能自动兑现一个 10 秒交付承诺。若业务关心的是承诺内交付，仅有连续变化的延迟统计还不够。反过来，阈值统计也没有描述超时到底严重到什么程度；二者回答不同问题。</p><h2 id="中位数下降-也可能只是慢任务退出成功样本" tabindex="-1">中位数下降，也可能只是慢任务退出成功样本 <a class="header-anchor" href="#中位数下降-也可能只是慢任务退出成功样本" aria-label="Permalink to &quot;中位数下降，也可能只是慢任务退出成功样本&quot;">​</a></h2><p>第二组成对输入保留四项原始延迟：5、6、12、20 秒。前一组全部成功，后一组仅将 12 秒和 20 秒两项标为失败。没有任何任务执行得更快。</p><table tabindex="0"><thead><tr><th>内部合成对照</th><th style="text-align:right;">成功数</th><th style="text-align:right;">成功任务中位延迟</th><th style="text-align:right;">尝试数</th><th style="text-align:right;">按期数</th><th style="text-align:right;">按期比例</th></tr></thead><tbody><tr><td>四项均成功</td><td style="text-align:right;">4</td><td style="text-align:right;">9 秒</td><td style="text-align:right;">4</td><td style="text-align:right;">2</td><td style="text-align:right;">0.5</td></tr><tr><td>两项慢任务标为失败</td><td style="text-align:right;">2</td><td style="text-align:right;">5.5 秒</td><td style="text-align:right;">4</td><td style="text-align:right;">2</td><td style="text-align:right;">0.5</td></tr></tbody></table><p>来源：同日内部实验的成功样本筛选前后对照。该模块对成功任务的有效延迟计算分位数，对全部已记录尝试计算按期比例。</p><p>中位延迟改善与交付比例不变，在这里来自样本选择，而不是截止期平台。两种机制不能合成一个加速比。成功任务分位数本身仍然有用，但必须明确它描述的是成功人群，并同时披露尝试、成功和按期计数。</p><p>另一个内部对照放入一项 5 秒成功任务、一项 6 秒失败任务、一项缺失延迟但标为成功的任务，以及一项 12 秒成功任务。模块输出尝试数 4、成功数 3、按期数 1，按期比例 0.25。失败和缺失延迟都没有从尝试分母里消失。不过，这个分母只能覆盖已经记录的尝试；它无法替调用方发现根本没有写入记录的任务。</p><h2 id="原始时间和运行有效性-仍在数字之外" tabindex="-1">原始时间和运行有效性，仍在数字之外 <a class="header-anchor" href="#原始时间和运行有效性-仍在数字之外" aria-label="Permalink to &quot;原始时间和运行有效性，仍在数字之外&quot;">​</a></h2><p>任务中可能有外部等待。一个内部控制同时提供 12 秒原始墙钟延迟和 1 秒净延迟，固定模块优先使用前者，仍给出零按期任务。把等待从某个局部计时中扣除，并不会缩短读者实际经历的到达至完成时间。</p><p>运行有效性也不能从指标为正来倒推。内部控制把一项 5 秒成功任务所在运行标为无效，模块仍返回 0.05 任务/秒及按期比例 1；这些数字可以用于诊断，却不自动授权把该运行纳入有效性能比较。另一个容量辅助函数对照包含三个合成负载单元：负载 1 有效且达标，负载 2 数字达标但无效，负载 3 有效但未达标。它在 0.9 达标目标下返回最大已测合格负载 1，已过滤无效运行。这不是实测负载扫描，也不构成该实现有缺陷的结论。</p><p>观测窗口则由调用方负责。<a href="https://arxiv.org/html/2610.40293v2" target="_blank" rel="noreferrer">论文第二版的完整任务计数说明</a>区分到达窗口内的按期吞吐，与包含队列排空时间的按期任务速率。前者按固定到达窗口计时，后者与词元吞吐使用窗口长度和队列完成时长中的较大者。指标模块接收一个时长参数，不能自行重建论文所需的到达批次和排空窗口。</p><h2 id="论文里的性能结果-是另一层证据" tabindex="-1">论文里的性能结果，是另一层证据 <a class="header-anchor" href="#论文里的性能结果-是另一层证据" aria-label="Permalink to &quot;论文里的性能结果，是另一层证据&quot;">​</a></h2><p>这些模块机制与<a href="https://arxiv.org/html/2610.40293v2" target="_blank" rel="noreferrer">论文第二版第 6.6 节及高负载结果表</a>提出的问题相关，但不是论文硬件实验的复现。作者报告，在最高负载下，把依赖图执行方式的缓存预算从 16 提高到 40 吉字节，成对分块的词元吞吐比中位数为 1.0774，完整任务第 95 百分位延迟比中位数为 0.8451；按截止期计的吞吐中位数仍接近零，一个成对分块还少了一项按期任务。</p><p>这组作者报告不能套进本文四任务表格，也不能同请求并发上限敏感性实验合并计算收益。它有独立的负载、模型与硬件条件、配对单元和截止期。论文还保留低负载、宽松或严格截止期下的持平情形，以及随任务绑定而变的结果。因此本次解释只支持“不同指标可能分离”，不支持普遍的执行策略或缓存配置排名。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>本篇使用同日已完成的研究对象。内部实验的 9 个控制均已执行并通过；<a href="/joinwell52/assets/evidence/2026-11-04-sig-20261104-006/sig-20261104-006-evidence.json">合成输入、预期和实际输出</a>随候选材料保留。模块固定于公开提交 <code>22483ab5df5eff562061953d564aac47a9423c2f</code>。实验首轮的唯一断言差异来自浮点表示：预期 5.99，实际为 5.989999999999999；研究阶段保留首轮结果，仅将比较改为数值容差后通过。本次写作没有重跑或增加实验。</p><p><a href="https://raw.githubusercontent.com/ShengxuanQiu/MAServeBench/22483ab5df5eff562061953d564aac47a9423c2f/mas_workflow/app/semantic/metrics.py" target="_blank" rel="noreferrer">任务指标代码</a>是规则的公开一手实现；上述执行是内部实验依据，没有独立复现者。硬件结果来自<a href="https://arxiv.org/html/2610.40293v2" target="_blank" rel="noreferrer">第二版论文</a>，保留为作者报告。<a href="https://raw.githubusercontent.com/ShengxuanQiu/MAServeBench/22483ab5df5eff562061953d564aac47a9423c2f/docs/REPRODUCIBILITY.md" target="_blank" rel="noreferrer">复现范围说明</a>另说明，清理后的公开核心不包含原始机器相关结果档案，模拟测试不能代替论文硬件结果。</p><p>发表不等于验证，引用不等于背书，同行评审不等于证明；来源自报不等于独立证据，一次模块执行成功不等于一般性能结论成立。</p><h2 id="要判断优化因果-还缺哪些实验" tabindex="-1">要判断优化因果，还缺哪些实验 <a class="header-anchor" href="#要判断优化因果-还缺哪些实验" aria-label="Permalink to &quot;要判断优化因果，还缺哪些实验&quot;">​</a></h2><p>我们没有原始冻结输入集、私有结果档案或完整模型与硬件服务栈；本次没有请求吞吐、真实到达过程、缓存、回放执行器或硬件分析器测量。三个容量单元也是合成摘要。固定公开提交和原始论文实验版本必须分开登记。</p><p>工程评估可以先保留一组共同读数：完整任务原始墙钟延迟、尝试与成功及按期计数、预先锁定的截止期、明确的观测窗口，以及运行有效性。接下来需要在可获得的冻结输入和硬件配置上，重复原生执行与回放对照，确认任务绑定、到达变化和模型差异是否改变结果。只有这些证据才能进一步回答：某项优化究竟使更多任务按期交付，还是只让一个更窄的统计量变好。</p>',29))])}const m=l(s,[["render",g]]);export{f as __pageData,m as default};
